// SCRATCH FILE — SFCC-831 prompt-drawer height fix verification. Deleted at end of step.
import { chromium } from 'playwright';

const VIEWPORT_MOBILE = { width: 440, height: 956 };
const VIEWPORT_DESKTOP = { width: 1440, height: 900 };

const STORIES = {
  location: 'layout-zimmcountrylanguagemismatch--location',
  language: 'layout-zimmcountrylanguagemismatch--language',
};

async function measure(page, storyId, viewport) {
  await page.setViewportSize(viewport);
  await page.goto(`http://localhost:6006/iframe.html?id=${storyId}&viewMode=story`, {
    waitUntil: 'networkidle',
  });
  await page.waitForSelector('[role="dialog"]', { timeout: 15000 });
  // Let framer-motion's enter transition (300ms, per DRAWER_TRANSITION) settle so the measured
  // rect isn't mid-slide.
  await page.waitForTimeout(500);
  return page.evaluate(() => {
    const dialog = document.querySelector('[role="dialog"]');
    const rect = dialog.getBoundingClientRect();
    const style = getComputedStyle(dialog);
    const buttons = Array.from(dialog.querySelectorAll('button'));
    const lastButtonBottom = buttons.length
      ? Math.max(...buttons.map((b) => b.getBoundingClientRect().bottom))
      : null;
    return {
      panelHeightPx: rect.height,
      panelTopPx: rect.top,
      panelBottomPx: rect.bottom,
      cssHeight: style.height,
      cssBottom: style.bottom,
      lastButtonBottomPx: lastButtonBottom,
      gapPx: lastButtonBottom !== null ? rect.bottom - lastButtonBottom : null,
      buttonCount: buttons.length,
    };
  });
}

const browser = await chromium.launch();
const page = await browser.newPage();

console.log('=== Location story — mobile 440x956 ===');
console.log(await measure(page, STORIES.location, VIEWPORT_MOBILE));

console.log('\n=== Language story — mobile 440x956 ===');
console.log(await measure(page, STORIES.language, VIEWPORT_MOBILE));

console.log('\n=== Location story — desktop 1440x900 (should be full height, unaffected) ===');
console.log(await measure(page, STORIES.location, VIEWPORT_DESKTOP));

console.log('\n=== Language story — desktop 1440x900 (should be full height, unaffected) ===');
console.log(await measure(page, STORIES.language, VIEWPORT_DESKTOP));

await browser.close();

